"""Periodic health snapshot of the run, logged as one line every 30 s: open tabs per website, machine load and free
memory. It shows whether pages that stop loading coincide with many tabs or a busy machine."""
import asyncio
import os

from . import llm
from .log import log


def snapshot(sites: dict) -> dict:
    pages = {}
    for site_id, site in sites.items():
        try:
            pages[site_id] = len(site.context.pages)
        except Exception:          # a closed browser must not break the monitor
            pages[site_id] = None
    try:
        load = [round(x, 2) for x in os.getloadavg()]
    except OSError:
        load = None
    return {"pages": pages, "load": load, "mem_available_mb": _mem_available_mb()}


def _mem_available_mb() -> int | None:
    try:
        with open("/proc/meminfo") as handle:
            for line in handle:
                if line.startswith("MemAvailable:"):
                    return int(line.split()[1]) // 1024
    except OSError:
        return None
    return None


async def monitor(sites: dict, every: float = 30.0) -> None:
    while True:
        await asyncio.sleep(every)
        log("health", **snapshot(sites), llm_calls=llm.usage["calls"])

