"""dev/eval/timeline.py: where a run's time and tokens went, from a local log or a platform run_logs export."""
import importlib.util
from pathlib import Path

_spec = importlib.util.spec_from_file_location("timeline", Path(__file__).parents[1] / "eval/timeline.py")
timeline = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(timeline)

LOG = """\
{"t": 0.01, "event": "run", "run_id": null}
{"t": 20.0, "event": "llm", "tag": "brief", "s": 19.5, "tokens": [2953, 657, 0]}
[00:22.0] stdout: {"t": 21.0, "event": "llm", "tag": "tender@tp", "s": 1.2, "tokens": [3700, 28, 3136]}
{"t": 21.1, "event": "action", "mission": "tender@tp", "step": 1, "tool": "click", "args": {}, "result": "ok"}
{"t": 30.0, "event": "llm", "tag": "extract:positions", "s": 8.5, "tokens": [1500, 300, 0]}
{"t": 30.1, "event": "action", "mission": "tender@tp", "step": 2, "tool": "extract", "args": {}, "result": "1 pos
{"t": 31.0, "event": "llm", "tag": "erp:G-1@erp", "s": 2.0, "tokens": [4000, 30, 1568]}
{"t": 90.0, "event": "evidence_done", "missions": []}
{"t": 95.0, "event": "timeline", "final": true, "phases": {"brief": [0.5, 20.0], "evidence": [20.0, 90.0]}, "missions": [{"name": "tender", "site": "tp", "start": 20.0, "end": 31.0, "status": "complete", "steps": 2, "llm_calls": 2, "llm_s": 3.2, "extractions": 1, "tools": {"extract": [1, 8.6], "click": [1, 0.3]}}]}
"""


def test_summary_reads_both_log_formats_and_truncated_lines():
    s = timeline.summarize(LOG.splitlines())
    groups = s["llm"]
    assert groups["brief"]["calls"] == 1 and groups["brief"]["out"] == 657
    assert groups["nav:tender"]["calls"] == 1 and groups["nav:tender"]["cached"] == 3136
    assert groups["nav:erp"]["calls"] == 1                     # ERP groups add up to one row
    assert groups["extract:positions"]["seconds"] == 8.5
    assert s["actions"]["tender@tp"] == 2                       # the truncated action line still counts
    assert s["events"]["evidence_done"] == 90.0
    assert s["timeline"]["missions"][0]["name"] == "tender"
    assert s["timeline"]["phases"]["evidence"] == [20.0, 90.0]


def test_report_names_the_slowest_tool_of_each_mission():
    text = timeline.report(timeline.summarize(LOG.splitlines()))
    assert "tender" in text and "extract 8.6s" in text and "brief" in text

"""Where a run's time and tokens went: phases, missions, model calls by group, notable events.

Reads a local log (JSON lines on stdout) or a platform `run_logs` export ("[mm:ss.s] stdout: {...}"). Lines cut at
the 4,000-character log limit are still counted by their event name and time.

  uv run --project agent python dev/eval/timeline.py dev/runs/x.log
"""
import json
import re
import sys
from collections import defaultdict

_HEAD = re.compile(r'\{"t": ([\d.]+), "event": "(\w+)"')
_MISSION = re.compile(r'"mission": "([^"]+)"')
NOTABLE = ("brief", "evidence_done", "review_check", "dry_run_stop", "submitted", "submit_phase_done", "exit")
COUNTED = ("llm_error", "llm_hedge", "llm_hedge_won", "goto_error", "tab_replaced", "fresh_tab", "settle_timeout",
           "mission_loop_abort", "mission_budget_exhausted", "mission_deadline", "extract_timeout")


def _events(lines):
    for line in lines:
        start = line.find('{"t": ')
        if start < 0:
            continue
        raw = line[start:]
        try:
            yield json.loads(raw, strict=False)
        except ValueError:
            head = _HEAD.match(raw)
            if head:
                event = {"t": float(head.group(1)), "event": head.group(2), "_cut": True}
                mission = _MISSION.search(raw)
                if mission:
                    event["mission"] = mission.group(1)
                yield event


def _group(tag: str) -> str:
    if tag.startswith(("extract:", "submit:", "vision")):
        return tag.split("@")[0]
    if tag == "brief" or tag.startswith("brief"):
        return tag
    return "nav:" + re.split(r"[:@]", tag)[0]


def summarize(lines) -> dict:
    llm = defaultdict(lambda: {"calls": 0, "in": 0, "out": 0, "cached": 0, "seconds": 0.0})
    actions, events, counts = defaultdict(int), {}, defaultdict(int)
    timeline = None
    for e in _events(lines):
        name = e["event"]
        if name == "llm":
            g = llm[_group(e.get("tag", ""))]
            tokens = (e.get("tokens") or [0, 0, 0]) + [0, 0, 0]
            g["calls"] += 1
            g["in"] += tokens[0] or 0
            g["out"] += tokens[1] or 0
            g["cached"] += tokens[2] or 0
            g["seconds"] = round(g["seconds"] + (e.get("s") or 0), 2)
        elif name == "action" and e.get("mission"):
            actions[e["mission"]] += 1
        elif name == "timeline" and not e.get("_cut"):
            if timeline is None or e.get("final") or not timeline.get("final"):
                if timeline and timeline.get("final") == e.get("final"):   # continuation lines of one timeline
                    timeline["missions"] += e.get("missions") or []
                    timeline["phases"] = e.get("phases") or timeline["phases"]
                else:
                    timeline = {"final": e.get("final"), "phases": e.get("phases") or {},
                                "missions": list(e.get("missions") or [])}
        if name in NOTABLE and name not in events:
            events[name] = e["t"]
        if name in COUNTED:
            counts[name] += 1
    return {"llm": dict(llm), "actions": dict(actions), "events": events, "counts": dict(counts),
            "timeline": timeline}


def report(s: dict) -> str:
    out = []
    t = s.get("timeline")
    if t:
        out.append("phases: " + ", ".join(f"{k} {v[0]:.0f}-{v[1]:.0f}s ({v[1] - v[0]:.0f}s)"
                                          for k, v in (t.get("phases") or {}).items()))
        out.append(f"{'mission':28} {'site':16} {'start':>6} {'end':>6} {'dur':>5} {'steps':>5} {'llm':>4} "
                   f"{'llm_s':>6} {'extr':>4}  slowest tools")
        for m in sorted(t["missions"], key=lambda m: m["start"]):
            tools = sorted((m.get("tools") or {}).items(), key=lambda kv: -kv[1][1])[:3]
            out.append(f"{m['name'][:28]:28} {m['site'][:16]:16} {m['start']:6.0f} {m['end']:6.0f} "
                       f"{m['end'] - m['start']:5.0f} {m['steps']:5} {m['llm_calls']:4} {m['llm_s']:6.1f} "
                       f"{m['extractions']:4}  " + ", ".join(f"{k} {v[1]}s" for k, v in tools)
                       + (" (running)" if m.get("running") else ""))
    out.append(f"\n{'model calls':24} {'calls':>5} {'in':>9} {'cached':>9} {'out':>7} {'sec':>7}")
    for name, g in sorted(s["llm"].items(), key=lambda kv: -(kv[1]["in"] - kv[1]["cached"])):
        out.append(f"{name[:24]:24} {g['calls']:5} {g['in']:9} {g['cached']:9} {g['out']:7} {g['seconds']:7.0f}")
    if s["events"]:
        out.append("\nevents: " + ", ".join(f"{k} {v:.0f}s" for k, v in s["events"].items()))
    if s["counts"]:
        out.append("counts: " + ", ".join(f"{k} {v}" for k, v in sorted(s["counts"].items())))
    return "\n".join(out)


