async def _site(p, submitted: list):
    browser = await p.chromium.launch()
    context = await browser.new_context()

    async def handle(route):
        url = urlparse(route.request.url)
        if url.path == "/next":
            submitted.append({k: v[0] for k, v in parse_qs(url.query).items()})
            body = "<html><body><h1>Gespeichert</h1></body></html>"
        else:
            body = FORM
        await route.fulfill(status=200, content_type="text/html; charset=utf-8", body=body)

    await context.route(f"{BASE}/**", handle)
    site = Site("config", BASE, {"username": "u", "password": "p"}, context)
    await site.start()
    return browser, site


def _run(fields, apply="Auswahl anwenden", then_click="Weiter", by_ref=False):
    submitted = []

    async def scenario():
        async with async_playwright() as p:
            browser, site = await _site(p, submitted)
            observation = await site.observe()
            if by_ref:      # the model addresses fields by the refs of the observation it saw before the call
                for field in fields:
                    field["ref"] = re.search(r"\[(\w+)\] \w+(?:\[\w+\])? \"" + field.pop("field"), observation).group(1)
            result = await site.act("fill_form", {"fields": fields, "apply": apply, "then_click": then_click})
            await browser.close()
            return result
    return asyncio.run(scenario()), submitted


