# ---------------------------------------------------------------- controls of an observation (for fill_form)
FIELD_KINDS = ("select", "input", "textarea", "checkbox", "radio", "slider")
PRESS_KINDS = ("button", "link", "summary", "tab", "menuitem", "option", "switch")
_CONTROL = re.compile(r'^\[(?P<ref>(?:f\d+)?e\d+)\] (?P<kind>[\w-]+)(?:\[[^\]]*\])? "(?P<name>.*?)"'
                      r'(?P<rest>(?: options:| value=| \[x\]| \[ \]| ->| \(| \[info:| expanded=| min=).*|)$')
_DISABLED = re.compile(r"\((?:[\w/-]+, )*disabled(?:, [\w/-]+)*\)")
_REF_ONLY = re.compile(r"\[?((?:f\d+)?e\d+)\]?")


def _controls(observation: str) -> list[dict]:
    found = []
    for line in observation.splitlines():
        match = _CONTROL.match(line.strip())
        if match:
            found.append({"ref": match.group("ref"), "kind": match.group("kind"), "name": match.group("name"),
                          "disabled": bool(_DISABLED.search(match.group("rest")))})
    return found


def _norm(label) -> str:
    return re.sub(r"\s+", " ", str(label or "")).strip().strip(":*").strip().casefold()


def _find(controls: list[dict], label: str, occurrence: int, kinds: tuple) -> tuple[dict | None, str]:
    """The control with this label (the n-th of that name), else the only one whose label contains it."""
    want, pool = _norm(label), [c for c in controls if c["kind"] in kinds]
    exact = [c for c in pool if _norm(c["name"]) == want]
    if len(exact) > occurrence:
        return exact[occurrence], ""
    partial = [c for c in pool if want and want in _norm(c["name"])]
    if len(partial) == 1:
        return partial[0], ""
    names = " | ".join(dict.fromkeys(f'"{c["name"]}"' for c in pool))[:600]
    why = f"{len(partial)} controls match {label!r}, use the exact label" if partial else f"no control {label!r}"
    return None, f"{why}. Here: {names}"


def _address(controls: list[dict], spec: dict, kinds: tuple) -> tuple[str, int] | str:
    """(label, occurrence) for a control given by label or by a ref of the current page; else why not."""
    given = str(spec.get("target") or spec.get("field") or spec.get("label") or spec.get("ref") or "").strip()
    ref = _REF_ONLY.fullmatch(given)
    if not ref:
        return (given, 0) if given else "no label or ref given"
    hit = next((c for c in controls if c["ref"] == ref.group(1)), None)
    if hit is None or hit["kind"] not in kinds:
        return f"{given} is not a {'field' if kinds is FIELD_KINDS else 'button'} on the current page"
    same = [c for c in controls if c["kind"] in kinds and _norm(c["name"]) == _norm(hit["name"])]
    return hit["name"], same.index(hit)

